"""Pure-array helpers for element-wise dataset arithmetic."""

from __future__ import annotations

import numpy as np


def grids_compatible(grid_a: list, grid_b: list, rtol: float = 1e-9) -> bool:
  """Compare coordinates relative to their extent, allowing roundoff at offsets.

  A fixed absolute tolerance would merge distinct microscopic domains; a
  tolerance proportional to the coordinate origin would merge shifted meshes
  at large offsets. Use the domain extent plus floating-point roundoff.
  """
  if len(grid_a) != len(grid_b):
    return False
  for a, b in zip(grid_a, grid_b):
    if a.shape != b.shape:
      return False
    if a.size == 0:
      continue
    extent = max(np.ptp(a), np.ptp(b))
    roundoff = 8 * np.finfo(float).eps * np.maximum(np.abs(a), np.abs(b))
    if not np.all(np.abs(a - b) <= rtol * extent + roundoff):
      return False
  return True


def grid_is_prefix(small: list, big: list, rtol: float = 1e-9) -> bool:
  """Whether ``small`` is exactly the leading dimensions of ``big`` (same
  shapes & nodes) -- the conf-space/phase-space compatibility check for
  cross-basis (conf x phase) operations, where a phase-space grid extends a
  lower-dimensional conf-space grid with extra (velocity-space) dimensions."""
  if not 0 < len(small) < len(big):
    return False
  return grids_compatible(small, big[:len(small)], rtol=rtol)
"""Integrate cell averages or point samples on separable grids (pure NumPy).

``grad``/``div``/``curl`` are deliberately absent: the ``src_bak`` originals
are unimplemented placeholders (``...`` bodies, no arguments) -- there is no
real numerics to port. The vector-calculus operators that *are* implemented
live in :mod:`postgkyl.numerics.ev_ops` (``divergence``/``curl``/``grad``),
expressed the same way, over ``(grid, values)`` pairs.
"""

from __future__ import annotations

import numpy as np


def _split_axis_string(axis: str) -> tuple:
  """Parse a comma-separated (``"0,1"``) or colon-sliced (``"0:2"``) axis
  string, or a bare integer string, into a tuple of integer axes.

  Shared with :func:`postgkyl.numerics.ev_ops._parse_axis`, whose outer
  type-dispatch differs (it also accepts ``float``/``np.ndarray``/``"all"``)
  but delegates this exact string-parsing branch here, so the comma/colon
  grammar has one home (Doctrine V) instead of two copies that could drift.
  """
  if len(axis.split(",")) > 1:
    return tuple(int(a) for a in axis.split(","))
  if len(axis.split(":")) == 2:
    lo, hi = axis.split(":")
    return tuple(range(int(lo), int(hi)))
  return (int(axis), )


def parse_axis(axis: int | tuple | str | None, num_dims: int) -> tuple:
  """Turn an axis selector into a tuple of integer axes."""
  if axis is None:
    return tuple(range(num_dims))
  if isinstance(axis, int):
    return (axis, )
  if isinstance(axis, tuple):
    return axis
  if isinstance(axis, str):
    return _split_axis_string(axis)
  raise TypeError(
      "'axis' needs to be integer, tuple, string of comma separated "
      "integers, or a slice ('int:int')")


def integrate(
    grid: list[np.ndarray],
    values: np.ndarray,
    axis: int | tuple | str | None = None
) -> tuple[list[np.ndarray], np.ndarray]:
  """Integrate cell averages or point samples over one or more axes.

  An axis with one more coordinate than values contains cell edges: sum
  each cell's average times its width. An axis matching the value count
  contains point samples: use the composite trapezoidal rule between the
  supplied points. Both rules support nonuniform meshes. A single point
  spans zero length. Packed DG data must be integrated before materializing
  it as a point mesh, since that mesh can lose cell-local polynomial meaning.

  Args:
    grid: Edge or point coordinate arrays, one per spatial dimension.
    values: Data array; the last axis is components, the rest are spatial.
    axis: Axis (or axes) to integrate over: an ``int``, a ``tuple`` of
      ``int``, a comma-separated string (``"0,1"``), a colon slice string
      (``"0:2"``), or ``None`` (integrate over every spatial axis).

  Returns:
    ``(grid, values)`` with the integrated axes collapsed to a single,
    grid-mean cell and ``values`` reduced accordingly (shape retained via
    ``expand_dims``).

  Raises:
    TypeError: If ``axis`` is not an int, tuple, or string.
  """
  grid = list(grid)
  values = np.copy(values)
  axis = parse_axis(axis, len(grid))

  for ax in sorted(axis, reverse=True):
    coord = np.asarray(grid[ax])
    if coord.ndim != 1:
      raise ValueError("separable integration requires one-dimensional axes")
    count = values.shape[ax]
    if len(coord) == count + 1:
      values = np.tensordot(values, np.diff(coord), axes=(ax, 0))
    elif len(coord) == count:
      values = np.trapezoid(values, x=coord, axis=ax)
    else:
      raise ValueError(
          f"axis {ax}: coordinate count {len(coord)} must match {count} "
          f"point samples or {count + 1} cell edges")

  for ax in sorted(axis):
    grid[ax] = np.array([grid[ax].mean()])
    values = np.expand_dims(values, ax)

  return grid, values
"""Convert a nodal (edge) grid to its cell-centered equivalent."""

from __future__ import annotations

import numpy as np


def sample_coordinates(coord: np.ndarray, count: int) -> np.ndarray:
  """Locate ``count`` samples on a separable point or cell-edge axis.

  Coordinates matching the sample count are already point locations. One
  extra coordinate denotes cell edges, whose samples live at the midpoints.
  No domain extent is inferred beyond the supplied coordinates.
  """
  coord = np.asarray(coord)
  if coord.ndim != 1:
    raise ValueError("sample coordinates require a one-dimensional axis")
  if len(coord) == count:
    return coord
  if len(coord) == count + 1:
    return 0.5 * (coord[:-1] + coord[1:])
  raise ValueError(
      f"coordinate count {len(coord)} must match {count} samples or "
      f"{count + 1} cell edges")


def nodal_to_cell_centered_grid(grid: list[np.ndarray],
                                cells: np.ndarray,
                                meshgrid: bool = False) -> list[np.ndarray]:
  """Return the cell-centered grid corresponding to a nodal (edge) grid.

  Args:
    grid: List of NumPy arrays giving the nodal grid coordinates.
    cells: Number of cells in each dimension.
    meshgrid: If ``True`` and the coordinates are 1-D, return an
      ij-indexed meshgrid instead of the plain 1-D per-axis arrays.

  Returns:
    List of NumPy arrays giving the cell-centered grid coordinates.

  Raises:
    ValueError: If ``grid`` and ``cells`` disagree on the number of
      dimensions, or an axis is neither nodal nor already cell-centered.
  """
  num_dims = len(grid)
  grid_out = []
  if num_dims != len(cells):
    raise ValueError("Number dimensions for 'grid' and 'values' doesn't match")
  for d in range(num_dims):
    if len(grid[d].shape) == 1:
      grid_out.append(sample_coordinates(grid[d], cells[d]))
    else:
      if grid[d].shape[d] == cells[d]:
        grid_out.append(grid[d])
      elif grid[d].shape[d] == cells[d] + 1:
        if num_dims == 1:
          grid_out.append(0.5 * (grid[d][:-1] + grid[d][1:]))
        else:
          grid_out.append(0.5 * (grid[d][:-1, :-1] + grid[d][1:, 1:]))
      else:
        raise ValueError("Something is terribly wrong...")

  if meshgrid and num_dims > 1 and all(axis.ndim == 1 for axis in grid_out):
    return list(np.meshgrid(*grid_out, indexing="ij"))

  return grid_out
"""Parse index / value / slice selectors into NumPy indices (pure)."""

from __future__ import annotations

import numpy as np


def _find_nearest_index(array, value):
  if array is None:
    raise TypeError(
        "Float selector given but no coordinate array to match against.")
  if not np.isfinite(value):
    raise ValueError("Coordinate selector must be finite.")
  if len(array) == 0:
    raise ValueError("Cannot select from an empty coordinate array.")
  return int(np.argmin(np.abs(np.asarray(array) - value)))


def _string_to_index(value: str, array: np.ndarray | None) -> int:
  if not isinstance(value, str):
    raise TypeError("Value is not a string")
  if value.lstrip("-").isdigit():
    return int(value)
  return _find_nearest_index(array, float(value))


def idx_parser(value: int | float | str,
               array: np.ndarray | None = None,
               nodal: bool = False) -> int | slice | tuple:
  """Turn an int/float/str selector into an int index, ``slice``, or tuple.

  - int -> used as-is
  - float -> nearest sample, or nearest cell center for an edge array
  - ``"a,b,c"`` -> tuple of indices
  - ``"a:b"`` -> ``slice``
  - ``"a"`` -> single index

  ``nodal=True`` means the array contains sample positions, not cell edges.
  Equal distances choose the first index; outside coordinates choose an endpoint.
  """
  if array is not None and not nodal:
    array = 0.5 * (np.asarray(array[:-1]) + np.asarray(array[1:]))
  if isinstance(value, (int, np.integer)):
    return int(value)
  if isinstance(value, (float, np.floating)):
    return _find_nearest_index(array, value)
  if isinstance(value, str):
    if len(value.split(",")) > 1:
      return tuple(_string_to_index(i, array) for i in value.split(","))
    if len(value.split(":")) == 2:
      lo, hi = value.split(":")
      if lo == "":
        lo = "0"
      if hi == "":
        hi = str(len(array)) if array is not None else ""
      return slice(_string_to_index(lo, array),
                   _string_to_index(hi, array) if hi else None)
    return _string_to_index(value, array)
  raise TypeError(f"Unsupported selector type: {type(value)!r}")

